-- ----------------------------------------------------------------------------
-- Worldforged pickups (generated by WorldforgedRestore/tools/build_pickups.py)
-- ----------------------------------------------------------------------------
-- On CoA a Worldforged item is picked up as a world object: a bag, a bucket, a bone,
-- a packet - the object is named after the base item it holds, and opening it gives
-- that item to one character once, forever. This file restores that layer.
--
-- WHERE THE DATA COMES FROM (nothing invented)
--   templates  the union of every client gameobjectcache capture in the archive
--              (data/archive/gameobjectcache_union.json): entry, type, displayId,
--              name, size and Data0..Data23 exactly as the realm sent them.
--   family     the realm's own catalog (exil.es coa_db, 2026-09-13). Its
--              `gameobject_loot` names the item behind a loot id; a world pickup is
--              any object whose loot id (the cache's Data1) resolves there to an item
--              the catalog marks worldforged. 1,314 loot ids in the whole game do, and
--              every one of those items sits on the Base rung (tier 0) - so what you
--              pick up in the world is the base item, as intended.
--   loot       that same catalog row: item, chance, min/max, quest flag.
--   positions  the archive's per-object observations (one world XYZ per object), then
--              anchored to the realm's own dump where it names this same object: the dump
--              gives where that object was looted and how far the nearest object of that
--              entry stood from it, plus that object's stored height.
--              The catalog carries no object spawns at all - `gameobject_spawn` is
--              empty - so one observed position per object is the honest maximum.
--
-- SCOPE: 1,555 objects, 1,555 loot rows, 1,510 spawns.
--   primary (catalog loot)  : 1,312
--   namesake rule           : 123   (validated 96.3% against the catalog's own pairs)
--   realm dump evidence     : 120   (item looted 1-10 yd from that object)
--   without an observed position, so not spawned : 39
--   skipped, observation has no usable map       : 6
--
-- THREE DELIBERATE DEVIATIONS, each required by the one-loot-per-character rule
--   * Data3 (consumable) -> 0. A consumable chest despawns on loot and returns on a
--     respawn timer, which makes the pickup a realm-wide roll per respawn instead of
--     one open per character. Non-consumable keeps it in the world for everyone;
--     the core re-rolls its loot for each new opener (Player::SendLoot clears and
--     fills on GO_READY), and GameObject::Update returns it to GO_READY.
--   * Data2 (restock) -> 0, so the chest never enters the restock path.
--   * ScriptName 'worldforged_pickup' - the marker mod-worldforged-pickups keys on.
--     It is what makes an unspent pickup sparkle and a spent one inert for the
--     character who spent it, and nothing else. It is empty in every capture.
--
-- spawntimesecs is 0: not a recovered value, and not a guess either - the core never reads
-- it for an object like this one. GameObject::LoadGameObjectFromDB copies it into
-- m_respawnDelayTime, which is only consulted when something despawns the object; a chest
-- with consumable = 0 is never despawned, because GameObject::Update's GO_JUST_DEACTIVATED
-- branch sees !IsDespawnAtAction() and chestRestockTime == 0 and puts it straight back to
-- GO_READY, which is exactly the re-roll the next character needs. 0 is also the value the
-- core requires to stay quiet: ObjectMgr::LoadGameobjects only reports a 0 spawn time as an
-- error when IsDespawnAtAction() is true, and for a chest that is chest.consumable.
-- A 3600 here would have been invented data that no code path reads.
--
-- orientation/rotation: no source holds the realm's own facing for these objects, so each
-- spawn carries a stable per-object facing (build_pickups.py::facing_of) and the matching
-- unit quaternion - rotation0 = rotation1 = 0, rotation2 = sin(a/2), rotation3 = cos(a/2),
-- the convention the rest of `gameobject` uses. Arbitrary, but so was the realm's, and the
-- captures' zero quaternion is not unit-length, which the core rejects row by row.
--   Fix one in play with `.gobject near` then `.gobject turn <spawn id>` (no angle takes
--   your own facing) and `.gobject move <spawn id> [x y z]`; both write to `gameobject`.
--   Then `tools/export_overrides.py` records the difference in
--   data/placements/overrides.csv, which this generator re-applies - so the correction
--   outlives a re-import.
--
-- Idempotent: every statement clears what it wrote first - REPLACE INTO for the two
-- keyed tables, a key-scoped DELETE for each block of spawns. The repository's SQL lint
-- forbids deleting rows from gameobject_template in an update, so the templates are
-- REPLACE INTO: the same end state, and it also lands the captured fields on an entry a
-- previous run left behind with different fields. Apply to acore_world.
-- Companion: worldforged-character-loot.sql (acore_characters). Undo:
-- worldforged-pickups-revert.sql.
-- ----------------------------------------------------------------------------

START TRANSACTION;

-- Superseded: the first pass planted 56 'Worldforged Cache' chests (real objects, but
-- their loot table is not in any source we hold) at 6,672 invented positions taken
-- from item-location pins, plus an invented random-loot pool. Remove its spawns and its
-- loot. Its 56 template rows are deliberately not deleted here - no update may delete
-- from gameobject_template - and only a server that ran that unpublished pass has them;
-- the manual undo removes them by entry for anyone who did.
DELETE FROM `gameobject`          WHERE `id` IN (108602, 1134104, 1134867, 1205730, 1310400, 1310450, 1310550, 1310570, 1324220, 1324240, 1324310, 1324320, 1324350, 1324730, 1325750, 1325760, 1325800, 1325820, 1325830, 1325860, 1325870, 1325990, 1326000, 1326020, 1326080, 1326090, 1326110, 1326230, 1326240, 1326330, 1326340, 1326360, 1326380, 1326470, 1326480, 1326490, 1326500, 1326530, 1326580, 1326800, 1326890, 1326900, 1326970, 1326980, 1327000, 1327010, 1327020, 1327030, 1327040, 1327050, 1327060, 1327090, 1327130, 1327150, 1327170, 1344091);
DELETE FROM `gameobject_loot_template` WHERE `Comment` LIKE 'AscensionWorldforged:%';
DELETE FROM `reference_loot_template`  WHERE `Entry` = 88456;

-- Clear anything a previous run wrote: the whole spawn guid block and our loot rows, so
-- re-applying starts from the state an empty server would. The template rows are handled
-- by the REPLACE INTO below - keyed on entry, so a run that left a different ScriptName
-- behind is still re-tagged with the captured fields.
DELETE FROM `gameobject`             WHERE `guid` BETWEEN 6900001 AND 6901526;
DELETE FROM `gameobject_loot_template` WHERE `Comment` LIKE 'AscensionWorldforged:%';

-- ----------------------------------------------------------------------------
-- 1. The 1,555 pickup templates, field for field as captured.
--    Written with REPLACE INTO: an entry this file already wrote ends with these values
--    rather than colliding with the old row, and every column is listed, so the result
--    never depends on a table default.
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- 2. Loot: each pickup's own loot id -> its own base item, exactly as the realm had
--    it. 1,555 rows, one per (loot id, item). Keyed on (Entry, Item), so
--    REPLACE INTO again: a loot id that already carries this item ends with exactly
--    these values instead of failing on the existing row.
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- 3. Spawns: 1,510 pickups at their observed world positions.
--    Fixed guids ({GUID_BASE + 1}+) so re-running this file and the per-character
--    ledger (keyed on the spawn id) stay in step; the positions are the community
--    observations of that same object, one each.
-- ----------------------------------------------------------------------------
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6900001 AND 6900150;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6900151 AND 6900300;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6900301 AND 6900450;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6900451 AND 6900600;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6900601 AND 6900750;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6900751 AND 6900900;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6900901 AND 6901050;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6901051 AND 6901200;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6901201 AND 6901350;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6901351 AND 6901500;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 6901501 AND 6901510;

COMMIT;

-- Verification
--   select count(*) from gameobject_template where ScriptName='worldforged_pickup';        -- 1555
--   select count(*) from gameobject_loot_template where Comment like 'AscensionWorldforged:%';  -- 1555
--   select count(*) from gameobject where guid between 6900001 and 6901510;  -- 1510
--   select count(*) from gameobject_template where name='Worldforged Cache';     -- 0
--   select count(*) from reference_loot_template where Entry=88456;               -- 0
